INSERT INTO services (id,slug,name,short_description,icon,hero_headline,hero_subheadline,success_rate,sort_order,is_published,problem_description,recovery_process) VALUES ('32ed48e7-67b5-4bc1-a70b-2e8b410e1e0b','crypto-recovery','Cryptocurrency Recovery','Military-grade blockchain forensics to track and reclaim stolen Bitcoin, Ethereum, and USDT from fraudulent exchanges.','BlockchainForensics','Total Blockchain Dominance','Our forensic specialists pierce through mixers and obfuscated chains to reclaim your digital sovereignty.','98%',1,1,'Scammers use mixers and cross-chain hops to vanish. Standard investigators stop at the first hop.','We utilize private node-level data to unmask wallet clusters and coordinate with global law enforcement to freeze assets.');
