INSERT INTO testimonials (id,client_name,location,rating,quote,amount_recovered,scam_type,is_published,is_featured,sort_order) VALUES ('4950c97c-2f21-43ff-82b5-89e58359e7e4','Cameron U.','Auckland, NZ',5,'ChanAid''s intervention prevented a $91,000 wire transfer from completing. Their real-time alert system flagged my case as high-priority and their recall team contacted the recipient bank within two hours of the transfer.','$77k','exchange',1,0,108);
INSERT INTO testimonials (id,client_name,location,rating,quote,amount_recovered,scam_type,is_published,is_featured,sort_order) VALUES ('150e3af4-8df7-4ad4-94fd-08d9f0ffc506','Aroha V.','Christchurch, NZ',5,'After my exchange account was compromised and $53,000 withdrawn, ChanAid''s combination of technical forensics and consumer protection law created an irresistible case for the exchange''s insurers to settle. Full recovery.','$100k','exchange',1,0,109);
